<?php require_role('supervisor');$pageTitle='Supervisor Dashboard';$pageSubtitle='Student portfolio, reviews and upcoming sessions';$uid=(int)current_user()['id'];$projects=db_all("SELECT p.*,u.full_name student_name,u.matric_no FROM projects p JOIN users u ON u.id=p.student_id WHERE p.supervisor_id=? ORDER BY u.full_name",[$uid]);$pendingSessions=(int)(db_one("SELECT COUNT(*) c FROM sessions s JOIN projects p ON p.id=s.project_id WHERE p.supervisor_id=? AND s.status='requested'",[$uid])['c']??0);$reviews=(int)(db_one("SELECT COUNT(*) c FROM milestones m JOIN projects p ON p.id=m.project_id WHERE p.supervisor_id=? AND m.status='submitted'",[$uid])['c']??0);$upcoming=db_all("SELECT s.*,u.full_name student_name FROM sessions s JOIN projects p ON p.id=s.project_id JOIN users u ON u.id=p.student_id WHERE p.supervisor_id=? AND s.status IN('approved','rescheduled') AND s.scheduled_at>=CURRENT_TIMESTAMP ORDER BY s.scheduled_at LIMIT 5",[$uid]);include __DIR__.'/../includes/layout_top.php'; ?>
<div class="stats-grid"><div class="stat-card"><div class="stat-label">Assigned students</div><div class="stat-value"><?= count($projects) ?></div><div class="stat-note">Active project portfolio</div></div><div class="stat-card"><div class="stat-label">Session requests</div><div class="stat-value"><?= $pendingSessions ?></div><div class="stat-note">Awaiting a scheduling decision</div></div><div class="stat-card"><div class="stat-label">Milestone reviews</div><div class="stat-value"><?= $reviews ?></div><div class="stat-note">Submitted work awaiting feedback</div></div><div class="stat-card"><div class="stat-label">Upcoming sessions</div><div class="stat-value"><?= count($upcoming) ?></div><div class="stat-note">Approved future appointments</div></div></div>
<div class="dashboard-grid"><section><div class="card"><div class="card-header"><div><h2>Assigned student portfolio</h2><p>Progress is calculated from approved milestones.</p></div><a class="button small secondary" href="<?= e(url('index.php?page=supervisor-students')) ?>">Open portfolio</a></div><div class="student-grid"><?php foreach(array_slice($projects,0,6) as $p): $prog=progress_for_project((int)$p['id']); ?><article class="student-card"><div class="student-head"><div class="avatar"><?= e(strtoupper(substr($p['student_name'],0,1))) ?></div><div><h3><?= e($p['student_name']) ?></h3><p><?= e($p['matric_no']) ?></p></div></div><p class="muted" style="min-height:44px"><?= e($p['title']) ?></p><div class="kpi-bar"><span>Approved progress</span><strong><?= $prog ?>%</strong></div><div class="progress-track"><div class="progress-bar" data-progress="<?= $prog ?>"></div></div></article><?php endforeach; ?></div></div></section><aside><div class="card"><div class="card-header"><div><h3>Upcoming sessions</h3><p>Your next approved meetings</p></div></div><?php if(!$upcoming): ?><div class="empty-state">No upcoming sessions.</div><?php else: foreach($upcoming as $s): ?><div class="list-card"><div><h4><?= e($s['student_name']) ?></h4><p><?= e(format_date($s['scheduled_at'])) ?><br><?= e($s['agenda']) ?></p></div><span class="badge <?= status_class($s['status']) ?>"><?= e($s['status']) ?></span></div><?php endforeach; endif; ?></div><div class="card"><div class="card-header"><h3>Priority actions</h3></div><a class="button w-full mb-2" href="<?= e(url('index.php?page=supervisor-sessions')) ?>">Review <?= $pendingSessions ?> session request(s)</a><a class="button secondary w-full" href="<?= e(url('index.php?page=supervisor-milestones')) ?>">Review <?= $reviews ?> milestone(s)</a></div></aside></div>
<?php include __DIR__.'/../includes/layout_bottom.php'; ?>
